from pathlib import Path
from html import escape
import base64,json,re,math
ROOT=Path(__file__).resolve().parent


def range_control(id,label,lo,hi,step,default):
    return f'<label class="control" for="{id}"><span>{label} <output id="{id}-value">{default}</output></span><input id="{id}" type="range" min="{lo}" max="{hi}" step="{step}" value="{default}"></label>'


def select_control(id,label,options):
    return f'<label class="control" for="{id}"><span>{label}</span><select id="{id}">'+''.join(f'<option value="{key}">{text}</option>' for key,text in options)+'</select></label>'


def paragraphs(sections):
    return ''.join(f'<h3>{escape(heading)}</h3>'+''.join('<p>'+p+'</p>' for p in ps) for heading,ps in sections)

